function table(head,rows){return `<div class="scroll"><table><thead><tr>${head.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(v=>`<td>${v??'不适用'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function canvas(id,image){const c=$(id);c.width=image.width;c.height=image.height;const ctx=c.getContext('2d',{willReadFrequently:true});ctx.putImageData(new ImageData(new Uint8ClampedArray(image.pixels),image.width,image.height),0,0);return c;}
function readCanvas(id){const c=$(id);return{pixels:c.getContext('2d',{willReadFrequently:true}).getImageData(0,0,c.width,c.height).data,width:c.width,height:c.height};}
