s.stepRender=()=>{step();g.S17TeachingView?.magnify($('step-content'));};document.addEventListener('click',e=>{const b=e.target.closest('[data-tab],[data-step]');if(!b)return;if(b.dataset.tab)showTab(b.dataset.tab);if(b.dataset.step!=null){s.step=Number(b.dataset.step);s.stepRender();}});step();
g.S17TeachingView?.init(id==='s17-cuttings-lithology'?'m1':id==='s17-fluorescence-review'?'m3':id==='s17-drilltime-boundaries'?'m4':'m5',showTab);s.stepRender();
g.S17Inspect={snapshot:()=>({id:s.id,status:s.status,revision:s.revision,selected:s.selected,run:s.run?{runId:s.run.runId,config:s.run.config,metrics:s.run.metrics,method:s.run.method,summary:s.run.summary,counts:s.run.counts,stepCount:s.run.stepData?.length}:null,reviews:s.reviews}),evidence:()=>{s.assertReady();return s.exportEvidence();}};
