function crop(im,bbox,padding=3){const x0=Math.max(0,bbox[0]-padding),y0=Math.max(0,bbox[1]-padding),x1=Math.min(im.width,bbox[2]+padding),y1=Math.min(im.height,bbox[3]+padding),w=x1-x0,h=y1-y0,pixels=new Uint8ClampedArray(w*h*4);for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++)pixels.set(im.pixels.slice((y*im.width+x)*4,(y*im.width+x)*4+4),((y-y0)*w+x-x0)*4);return{width:w,height:h,pixels};}
function imageFor(scene,run,key,state={}){const o=run.observations||run,inf=run.inference;if(key==='raw'||key==='white')return o.white;if(key==='uv')return o.uv;if(scene==='m1'){const p=inf?.results[state.selected??1];if(key==='corrected'||key==='outlines')return inf?.image||o.white;if(key==='patch')return p?crop(inf.image,p.component.bbox):null;if(key.startsWith('neighbor')){const n=p?.prediction.neighbors[+key.slice(-1)],sample=n&&run.library.model.samples[n.index];return sample?crop(sample.image,sample.component.bbox):null;}}
 if(scene==='m3'&&inf){const p=inf.prepared,mask=inf.masks[state.method||'M0'],pixels=Uint8ClampedArray.from(o.uv.pixels);for(let i=0;i<p.width*p.height;i++){if(key==='score'){const z=inf.scores[i];pixels[i*4]=p.roi[i]?Math.round(245*z+70*(1-z)):235;pixels[i*4+1]=p.roi[i]?Math.round(70*z+100*(1-z)):231;pixels[i*4+2]=p.roi[i]?Math.round(60*z+135*(1-z)):225;}else if(key==='mask'){for(let c=0;c<3;c++)pixels[i*4+c]=mask[i]?[184,36,42][c]:p.roi[i]?232:249;}else if(key==='overlay'&&mask[i]){pixels[i*4]=Math.round(pixels[i*4]*.5+184*.5);pixels[i*4+1]=Math.round(pixels[i*4+1]*.5+36*.5);pixels[i*4+2]=Math.round(pixels[i*4+2]*.5+42*.5);}pixels[i*4+3]=255;}return{width:p.width,height:p.height,pixels};}return o.white||null;}
function selected(scene,run,state={}){if(scene==='m1')return state.selected===null?null:run.inference.results[state.selected??1]||null;if(scene==='m2')return state.selected===null?null:run.inference[state.selected||0]||null;if(scene==='m4'){let i=0,d=Infinity;run.observations.rows.forEach((r,j)=>{const diff=Math.abs(r.depthMD_m-(state.depth??1240));if(diff<d){i=j;d=diff;}});return{row:run.observations.rows[i],norm:run.inference.norm[i],assigned:run.inference.assigned[i],index:i};}if(scene==='m5')return run.inference.facts[state.selected??2]||run.inference.facts[0];return null;}
function proportion(run,key='model',state=null){const chosen=state?selected('m1',run,state):null,klass=chosen?(key==='baseline'?chosen.baseline:chosen.prediction.label):null;return ['count','area'].map(mode=>{const a=g.M1Core.proportions(run.inference.results,key,mode);return `<div class="wb-proportion"><b>${mode==='count'?'颗粒数':'可见面积'} · 分母 ${a.denominator}${mode==='count'?' 粒':' 像素'}</b><div class="wb-stack" aria-label="${mode==='count'?'颗粒数':'面积'}比例">${a.weights.map((v,i)=>`<i style="width:${a.denominator?v/a.denominator*100:0}%;background:${palette[i]};opacity:${chosen&&i!==klass ? .35 : 1};outline:${chosen&&i===klass?'2px solid #343A40':'none'};outline-offset:2px" title="${names.m1[i]} ${v}/${a.denominator}"></i>`).join('')}</div><div class="wb-proportion-labels">${a.weights.map((v,i)=>`<span><i style="background:${palette[i]}"></i>${names.m1[i]} ${v}/${a.denominator} · ${pct(a.fractions[i])}</span>`).join('')}</div></div>`;}).join('');}
function m1Features(run,state){const p=selected('m1',run,state);if(!p)return '<p class="wb-empty">原位置没有检出轮廓。这个位置不产生新的特征或分类；恢复观察条件后可继续对照。</p>';return `<div class="wb-feature-grid">${image('patch','选中颗粒的实际像素局部')}<div><h4>把能观察的线索变成数值</h4>${bars([{name:'平均红',value:p.x[0],color:red},{name:'平均绿',value:p.x[1],color:gold},{name:'平均蓝',value:p.x[2],color:blue}],{max:1,label:'当前颗粒的三个平均颜色通道'})}<p>相邻像素起伏：水平 ${fmt(p.x[6],4)}，垂直 ${fmt(p.x[7],4)}。形状紧致度 ${fmt(p.x[10],3)}。</p><p class="wb-note">颜色、纹理与形状共16项进入距离；${p.component.area}像素的面积只参与整盘汇总。</p></div></div>`;}
function m1Neighbors(run,state){const p=selected('m1',run,state);if(!p)return m1Features(run,state);return `<div class="wb-verdict-pair"><div><span>只看颜色的规则</span><b>${names.m1[p.baseline]}</b></div><div><span>颜色＋纹理＋形状 · kNN</span><b>${names.m1[p.prediction.label]}</b><small>加权票数占比 ${pct(p.prediction.support)}</small></div></div><div class="wb-neighbors">${p.prediction.neighbors.slice(0,3).map((n,i)=>`<article>${image('neighbor'+i,'近邻'+(i+1)+' · '+names.m1[n.label])}<b>距离 ${fmt(n.distance,3)}</b><span>票重 ${fmt(1/Math.max(.05,n.distance),2)}</span></article>`).join('')}</div>${bars(p.prediction.weights.map((v,i)=>({name:names.m1[i],value:v,color:palette[i]})),{label:'将相同类别的近邻票重相加'})}<p class="wb-note">距离使用16项标准化特征；参考颗粒来自参考照片纹理拼盘，演示使用另一张来源照片；当前输入只读取像素与参照值。较近的颗粒票重更大。</p>`;}
function gasChart(run,state={},kind='gas'){const s=selected('m2',run,state),all=run.observations.rows||[],W=width(state),pad=55,right=W-18,H=kind==='clocks'?385:kind==='components'?350:245;if(!all.length)return '<p>没有气测记录。</p>';const source=s?.features.sourceTime_s,lo=s?Math.max(all[0].time_s,Math.min(s.event.start_s-100,source==null?s.event.start_s-100:source-100)):all[0].time_s,hi=s?Math.min(all.at(-1).time_s,s.event.end_s+100):all.at(-1).time_s,rows=all.filter(r=>r.time_s>=lo&&r.time_s<=hi),x=t=>pad+(t-lo)/(hi-lo||1)*(right-pad);let body='';const cv=g.M2Core.cumulative(all),tracks=kind==='clocks'?[{label:'地面总气',key:r=>r.gas,color:red},{label:'排量 / L·s⁻¹',key:r=>r.flow*1000,color:blue},{label:'累计泵量 / m³',key:r=>cv[all.indexOf(r)],color:gold}]:kind==='components'?['gas','c1','c2','c3'].map((key,i)=>({label:['总气','C1 甲烷','C2 乙烷','C3 丙烷'][i],key:r=>r[key],color:[red,blue,gold,'#9b7286'][i]})):[{label:'总气 · 教学仪器读数',key:r=>r.gas,color:red}];const trackH=(H-65)/tracks.length;
 tracks.forEach((t,k)=>{const top=25+k*trackH,vals=rows.map(t.key),mn=kind==='clocks'&&k===2?Math.floor(Math.min(...vals)):0,mx=Math.max(mn+.01,...vals)*1.06,y=v=>top+trackH-22-(v-mn)/(mx-mn)*(trackH-37);body+=text(pad,top,t.label,t.color)+line([pad,top+trackH-22],[right,top+trackH-22],'#d7d4d0',1);body+=text(3,top+22,fmt(mx,kind==='components'&&k>1?2:1),muted,14)+text(3,top+trackH-17,fmt(mn,0),muted,14);if(s)body+=`<rect x="${x(s.event.start_s)}" y="${top+8}" width="${x(s.event.end_s)-x(s.event.start_s)}" height="${trackH-30}" fill="${red}" opacity=".055"/>`;body+=`<path d="${rows.map((r,i)=>(i?'L':'M')+x(r.time_s).toFixed(1)+','+y(t.key(r)).toFixed(1)).join(' ')}" stroke="${t.color}" stroke-width="2" fill="none"/>`;if(s)body+=line([x(s.event.time_s),top+6],[x(s.event.time_s),top+trackH-22],red,1.5,'4 4');if(kind==='clocks'&&source!=null)body+=line([x(source),top+6],[x(source),top+trackH-22],blue,2,'5 3');});
 for(let i=0;i<4;i++){const t=lo+(hi-lo)*i/3;body+=text(x(t),H-29,fmt(t/60,1),muted,14,'middle');}body+=text(W/2,H-5,'记录时间 / min',muted,16,'middle');if(kind==='clocks'&&s){body+=text(W-20,18,'红：到达　蓝：来源',muted,14,'end');for(const o of run.observations.operations){const a=Math.max(lo,o.start_s),b=Math.min(hi,o.end_s);if(b>a)body+=`<rect x="${x(a)}" y="${H-61}" width="${Math.max(2,x(b)-x(a))}" height="7" rx="2" fill="${o.type==='connection'?gold:blue}" opacity=".65"><title>${o.type==='connection'?'接单根':'起下钻'} ${clock(o.start_s)}—${clock(o.end_s)}</title></rect>`;}}
 return `<div class="wb-chart" data-wb-plot="gas" data-x0="${lo}" data-x1="${hi}" data-pad="${pad}" data-plot-width="${W}">${svg(W,H,kind==='clocks'?'同一时间轴的气测、排量和累计泵量':'实际气测曲线',body)}</div>`;}
function m2Candidates(run,state){const a=selected('m2',run,state);if(!a)return '<p class="wb-empty">当前阈值下没有候选气峰。原始曲线仍可查看。</p>';const b=run.comparison?.results[state.selected||0],context=run.config.context,plain=context?b:a,withOps=context?a:b;return `<div class="wb-verdict-pair"><div><span>只用峰形与组分</span><b>${names.m2[plain?.prediction.label]||'无对应峰'}</b><small>6维特征</small></div><div><span>加入来源工况</span><b>${names.m2[withOps?.prediction.label]||'无对应峰'}</b><small>11维特征</small></div></div><p>当前所用视角：<b>${context?'加入来源工况':'只看气测特征'}</b>。当前候选 <b>${names.m2[a.prediction.label]}</b>，支持度 ${pct(a.prediction.support)}；规则基线 ${names.m2[a.baseline]}。</p>${bars(a.prediction.neighbors.slice(0,3).map((n,i)=>({name:(i+1)+'. '+names.m2[n.label]+' · '+run.library.model.samples[n.index].group,value:n.distance,color:blue})),{label:'当前真实前三近邻的标准化距离'})}<p class="wb-note">两条路径共用当前载入的气测和日志，分别使用对应的训练尺度。${esc(a.prediction.reason.join('；'))}</p>`;}
function m3Pixel(run,state){const p=run.inference.prepared,point=state.point||[59,39],i=point[1]*p.width+point[0],k=p.indices.indexOf(i);if(k<0)return '<p class="wb-empty">当前点位于白光可见范围之外，不计入分子或分母。</p>';const fs=p.features[k],model=run.library.model,z=g.S17Math.scale(fs,model.scaler),contributions=z.map((v,j)=>v*model.weights[j+1]),sum=model.weights[0]+contributions.reduce((a,b)=>a+b,0),score=run.inference.scores[i];return `<p>像素 (${point.join(', ')})：五项贡献加基础项 ${fmt(model.weights[0],3)}，合计 <b>${fmt(sum,3)}</b>。</p>${bars(contributions.map((v,j)=>({name:['红通道','绿通道','蓝通道','颜色差','邻域反差'][j],value:v})),{signed:true,label:'当前像素五项特征对得分的实际贡献'})}<div class="wb-score"><span>映射为显示得分 <b>${fmt(score,3)}</b></span><div><i style="left:${score*100}%"></i><em style="left:${run.config.threshold*100}%"></em></div><span>阈值 ${fmt(run.config.threshold,2)} → <b>${score>=run.config.threshold?'选入':'不选入'}</b></span></div>`;}
function m3Baseline(run,state){const p=run.inference.prepared,i=state.point[1]*320+state.point[0];if(!p.roi[i])return '<p>当前像素不在白光可见范围内。</p>';const raw=state.method==='B0',rgb=raw?Array.from(run.observations.uv.pixels.slice(i*4,i*4+3)):Array.from(p.corrected.slice(i*3,i*3+3)),brightness=rgb.reduce((a,b)=>a+b,0)/3;return `<h4>${raw?'原始亮度阈值 B0':'参照校正阈值 B1'}</h4><p>当前同一像素的三通道均值：(${rgb.map(v=>fmt(v,2)).join(' ＋ ')}) ÷ 3 ＝ <b>${fmt(brightness,2)}</b>。</p><p>与亮度阈值45比较：<b>${brightness>=45?'选入':'不选入'}</b>。右侧掩膜采用同一方法。</p><p>选择“多特征逻辑回归”可查看 AI 的结果；亮度基线不使用逻辑回归得分阈值。</p>`;}
function m3Methods(run,state){const inf=run.inference;return `<div class="wb-method-list">${[['B0','原始亮度阈值'],['B1','参照校正阈值'],['M0','多特征逻辑回归']].map(([id,name])=>{const s=inf.summaries[id];return `<button type="button" data-wb-method="${id}" aria-pressed="${state.method===id}"><span>${name}</span><i><em style="width:${(s.area||0)*100}%"></em></i><b>${s.count.toLocaleString()} / ${s.denominator.toLocaleString()}<small>${pct(s.area)}</small></b></button>`;}).join('')}</div><p class="wb-note">同一白光范围作为分母。点击方法，在相同位置查看其实际掩膜。${esc(inf.prepared.quality.join('；'))}</p>`;}
function m4Tracks(run,state={}){const rows=run.observations.rows,W=width(state),mobile=W<520,stage=state.m4Track||'all',tracks=mobile?(stage==='raw'?['rop','ops']:stage==='groups'?['norm','group']:['rop','norm']):['rop','ops','norm','group'],top=72,bottom=335,H=375,min=rows[0].depthMD_m,max=rows.at(-1).depthMD_m,y=d=>top+(d-min)/(max-min||1)*(bottom-top),start=57,trackW=(W-start-12)/tracks.length,cur=selected('m4',run,state);let body='';
 [0,.25,.5,.75,1].forEach(q=>{const d=min+(max-min)*q;body+=line([start,y(d)],[W-8,y(d)],'#e3dfd9',1)+text(3,y(d)+5,fmt(d,0),muted,16);});tracks.forEach((kind,j)=>{const left=start+j*trackW+5,right=left+trackW-13;body+=`<rect x="${left-3}" y="${top-8}" width="${trackW-5}" height="${bottom-top+16}" rx="8" fill="#f1eee8"/>`;body+=text((left+right)/2,22,{rop:'原始钻速',ops:'钻压 / 转速',norm:'相对响应',group:'连续分段'}[kind],ink,mobile?16:16,'middle');
 if(kind==='group'){for(const p of run.inference.assigned)if(p.valid)body+=`<rect x="${left+10}" y="${y(p.depthMD_m)}" width="${Math.max(15,right-left-20)}" height="${Math.max(1,(bottom-top)/rows.length+1)}" fill="${palette[p.label%3]}" opacity=".65"/>`;for(const d of run.inference.boundaries)body+=line([left,y(d)],[right,y(d)],red,2);return;}
 const specs=kind==='ops'?[{values:rows.map(r=>r.WOB_kN),label:'WOB',color:blue},{values:rows.map(r=>r.RPM),label:'RPM',color:gold,dash:true}]:[{values:kind==='rop'?rows.map(r=>r.ROP_m_h):run.inference.norm.map(r=>r.valid?r.normalized:null),label:kind==='rop'?'m/h':'相对量',color:kind==='rop'?red:blue}];for(const spec of specs){const finite=spec.values.filter(Number.isFinite).concat([0]),lo=Math.min(...finite,0),hi=Math.max(...finite,.01),x=v=>left+(v-lo)/(hi-lo||1)*(right-left);let previous=false,path='';rows.forEach((r,i)=>{const v=spec.values[i];if(!g.M4Core.valid(r)||!Number.isFinite(v)){previous=false;return;}path+=(previous?'L':'M')+fmt(x(v),1)+','+fmt(y(r.depthMD_m),1)+' ';previous=true;});body+=`<path d="${path}" stroke="${spec.color}" fill="none" stroke-width="2" ${spec.dash?'stroke-dasharray="4 3"':''}/>`;body+=text((left+right)/2,kind==='ops'?(spec.dash?62:43):47,spec.label+' '+fmt(lo,kind==='norm'?2:0)+'—'+fmt(hi,kind==='norm'?2:0),spec.color,16,'middle');}if(kind==='rop')for(const d of run.inference.baseline)body+=line([left,y(d)],[right,y(d)],gold,2,'4 3');});
 body+=line([start,y(cur.row.depthMD_m)],[W-8,y(cur.row.depthMD_m)],red,1.5,'5 3');body+=text(W/2,H-12,'深度 / m MD · 沿井眼向下',muted,16,'middle');return `<div class="wb-chart" data-wb-plot="depth" data-depth-min="${min}" data-depth-max="${max}" data-y0="${top}" data-y1="${bottom}" data-plot-height="${H}">${svg(W,H,'共同深度轴的原始钻速、工况、相对响应和连续分段',body)}</div><p class="wb-note">朱红虚线穿过同一记录；赭金短线是原始钻速跳变。工况轨蓝灰为钻压kN、赭金为转速rev/min，各自标注量程。分段组号表示相似响应。</p>`;}
function m4Cluster(run,state={}){const W=width(state),H=280,model=run.library.models[run.config.k],cur=selected('m4',run,state);if(!cur.norm.valid)return '<p>当前是非钻进记录，曲线保留缺口，不参与聚类。</p>';const p=g.S17Math.scale(cur.norm.x,model.scaler),points=run.library.trainingView.map(v=>g.S17Math.scale(v,model.scaler)),bound=Math.max(2,...model.centers.flat().map(Math.abs),...p.map(Math.abs)),x=v=>55+(v+bound)/(2*bound)*(W-85),y=v=>H-45-(v+bound)/(2*bound)*(H-85);let body=line([55,H-45],[W-25,H-45],'#c8c6c1',1)+line([55,30],[55,H-45],'#c8c6c1',1);for(const a of points)body+=`<circle cx="${x(a[0])}" cy="${y(a[1])}" r="2.5" fill="${blue}" opacity=".16"/>`;model.centers.forEach((c,i)=>{body+=line([x(p[0]),y(p[1])],[x(c[0]),y(c[1])],palette[i],1.5,'4 3')+`<circle cx="${x(c[0])}" cy="${y(c[1])}" r="10" fill="${palette[i]}"/>`+text(x(c[0])+13,y(c[1])+5,'组'+String.fromCharCode(65+i),palette[i]);});body+=`<circle cx="${x(p[0])}" cy="${y(p[1])}" r="7" fill="white" stroke="${red}" stroke-width="3"/>`+text(x(p[0])+10,y(p[1])-10,'当前深度',red)+text(W/2,H-7,'标准化钻速响应 →',muted,16,'middle')+text(55,20,'标准化扭矩响应 ↑',muted,16);return svg(W,H,'当前点在两维响应空间中与实际训练组中心比较',body);}
function m5Scores(run,state={}){const f=selected('m5',run,state);if(!f)return '<p>没有可处理的子句。</p>';const max=Math.max(...f.prediction.scores);return `<p>候选栏目：${esc(g.M5Core.labels[f.prediction.proposedLabel])}；最终：${esc(g.M5Core.labels[f.prediction.label]||'待分类复核')}。词表覆盖 ${pct(f.prediction.knownFraction)}。${esc(f.prediction.reasons.join('；'))}</p>`+bars(f.prediction.scores.map((v,i)=>({name:g.M5Core.labels[i],value:v-max,color:i===f.prediction.proposedLabel?red:blue})),{signed:true,label:'当前子句相对最高类别的对数分数'});}
